// The sign-list rules against docs/contract/vectors/sign-rules.json (generated by the
// Python reference, tools/sign_rules.py) and the data file the app embeds.
import 'dart:convert';
import 'dart:io';

import 'package:test/test.dart';
import 'package:tn_display_protocol/tn_display_protocol.dart';

Map<String, Object?> _json(String path) =>
    jsonDecode(File(path).readAsStringSync()) as Map<String, Object?>;

List<String> _strs(Object? v) => (v! as List<Object?>).cast<String>();

void main() {
  final vec = _json('../../docs/contract/vectors/sign-rules.json');
  final data = _json('../../docs/contract/sign-rules.json');

  test('embedded data equals sign-rules.json', () {
    final signs = (data['signs']! as List<Object?>).cast<Map<String, Object?>>();
    expect(vendoredSigns, hasLength(signs.length));
    for (var i = 0; i < signs.length; i++) {
      expect(vendoredSigns[i].vzNr, signs[i]['vzNr']);
      expect(vendoredSigns[i].code, signs[i]['code']);
      expect(vendoredSigns[i].labelDe, signs[i]['labelDe']);
      expect(vendoredSigns[i].left, signs[i]['side'] == 'left');
    }
    expect(signRulesDisplayedPerColumn, signsDisplayed);
  });

  group('sequences', () {
    for (final seq in (vec['sequences']! as List<Object?>).cast<Map<String, Object?>>()) {
      test(seq['name']! as String, () {
        var lists = const SignLists.empty();
        for (final step in (seq['steps']! as List<Object?>).cast<Map<String, Object?>>()) {
          final vz = step['vzNr']! as String;
          List<String> removed = const [];
          if (step['op'] == 'add') {
            final r = addSign(lists, vz);
            lists = r.lists;
            removed = r.removed;
          } else {
            lists = removeSign(lists, vz);
          }
          expect(lists.left, _strs(step['left']), reason: 'left after ${step['op']} $vz');
          expect(lists.right, _strs(step['right']), reason: 'right after ${step['op']} $vz');
          expect(removed, _strs(step['removed']), reason: 'removed by ${step['op']} $vz');
          expect(lists.leftCodes, step['leftCodes']);
          expect(lists.rightCodes, step['rightCodes']);
        }
      });
    }
  });

  test('every sign: side and code', () {
    final sides = vec['sides']! as Map<String, Object?>;
    final codes = vec['codes']! as Map<String, Object?>;
    for (final s in vendoredSigns) {
      expect(signGoesLeft(s.vzNr) ? 'left' : 'right', sides[s.vzNr], reason: s.vzNr);
      expect(signCodeOf(s.vzNr), codes[s.vzNr], reason: s.vzNr);
    }
  });

  test('full conflict table (every new sign against every sign)', () {
    final table =
        (vec['conflictTable']! as Map<String, Object?>)['evicts']! as Map<String, Object?>;
    for (final n in vendoredSigns) {
      final expected = _strs(table[n.vzNr]);
      final actual = [
        for (final o in vendoredSigns)
          if (signConflicts(n.vzNr, o.vzNr)) o.vzNr,
      ];
      expect(actual, expected, reason: 'adding ${n.vzNr}');
    }
  });

  test('codes round trip', () {
    expect(signCodeOf('142-10'), 14210);
    expect(signCodeOf('276'), 27600);
    expect(signMajorOf('101-51'), 101);
  });
}
